// annotationPreview marks a command as a preview in its cobra annotations.
const annotationPreview = "intropy.io/preview"

// previewNote is appended to the Long help of preview commands.
const previewNote = "This command is a preview: it is under evaluation and may change or be removed in a future release."

// markPreview flags cmd as a preview: shipped for evaluation, not part of the
// golden path. It appends "(preview)" to the short help, the stability note
// to the long help, and records the annotation that Execute warns on.
func markPreview(cmd *cobra.Command) {
	cmd.Short += " (preview)"
	if cmd.Long != "" {
		cmd.Long += "\n\n" + previewNote
	}
	if cmd.Annotations == nil {
		cmd.Annotations = map[string]string{}
	}
	cmd.Annotations[annotationPreview] = "true"
}

// warnIfPreview prints the preview warning for cmd on stderr. It runs from the
// root's PersistentPreRunE so preview commands never shadow it with their own
// hooks; --help output carries the note instead, since help runs no hooks.
func warnIfPreview(cmd *cobra.Command) {
	if cmd.Annotations[annotationPreview] != "true" {
		return
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "warning: '%s' is a preview command and may change or be removed in a future release\n", cmd.CommandPath())
}
